examples.template:
VStack(alignment: .leading, spacing: 24) {
    MonarchBlockEditor({{label}}, blocks: $blocks)
        .frame(height: 1000)
    MonarchPageOutline(
        [
            MonarchPageOutlineHeading({{blocks.0.text}}, level: {{blocks.0.level}}, id: {{blocks.0.text}}),
            MonarchPageOutlineHeading({{blocks.2.text}}, level: {{blocks.2.level}}, id: {{blocks.2.text}}),
            MonarchPageOutlineHeading({{blocks.6.text}}, level: {{blocks.6.level}}, id: {{blocks.6.text}}),
            MonarchPageOutlineHeading({{blocks.8.text}}, level: {{blocks.8.level}}, id: {{blocks.8.text}}),
        ],
        currentID: {{blocks.0.text}},
        stats: MonarchPageOutlineStats(words: {{outline.words}}, minutes: {{outline.minutes}}),
        labels: MonarchPageOutlineLabels(title: {{outline.title}})
    ) { _ in }
    .frame(maxWidth: .infinity, alignment: .leading)
}

